{
  "name": "message-board",
  "version": "1.0.0",
  "description": "Real-time message board using PGLite and SSE",
  "scripts": {
    "dev:backend": "node server.js",
    "dev:frontend": "vite --host",
    "dev": "npm run dev:backend & npm run dev:frontend"
  },
  "dependencies": {
    "@electric-sql/pglite": "^0.2.4",
    "cors": "^2.8.5",
    "express": "^4.18.2"
  },
  "devDependencies": {
    "vite": "^5.0.0"
  },
  "allowScripts": {
    "esbuild@0.21.5": true
  }
}

const express = require('express');
const cors = require('cors');
const pgModule = require('@electric-sql/pglite');
// PGLite uses a lazy-loaded getter that requires `this` context to resolve
const PGLite = Object.getOwnPropertyDescriptor(pgModule, 'PGlite').get.call(pgModule);
const path = require('path');
const fs = require('fs');

const app = express();
const PORT = 3001;

// Middleware
app.use(cors());
app.use(express.json());

// Store active SSE connections
let sseConnections = [];

// PGLite data directory
const DATA_DIR = path.join(__dirname, 'pglite-data');

async function initDB() {
  // Ensure data directory exists
  if (!fs.existsSync(DATA_DIR)) {
    fs.mkdirSync(DATA_DIR, { recursive: true });
  }

  const db = new PGLite({
    WALMode: 'filesystem',
    filename: path.join(DATA_DIR, 'pglite')
  });

  await db.waitReady;

  // Create messages table if it doesn't exist
  await db.query(`
    CREATE TABLE IF NOT EXISTS messages (
      id SERIAL PRIMARY KEY,
      text TEXT NOT NULL,
      created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
    )
  `);

  return db;
}

let db;

async function startServer() {
  db = await initDB();
  console.log('PGLite database initialized');

  // GET /api/messages - Fetch all messages (historical data)
  app.get('/api/messages', async (req, res) => {
    try {
      const result = await db.query(
        'SELECT id, text, created_at FROM messages ORDER BY created_at ASC'
      );
      // Format dates as ISO strings
      const messages = result.rows.map(row => ({
        id: row.id,
        text: row.text,
        created_at: row.created_at instanceof Date
          ? row.created_at.toISOString()
          : new Date(row.created_at).toISOString()
      }));
      res.json(messages);
    } catch (err) {
      console.error('Error fetching messages:', err);
      res.status(500).json({ error: 'Failed to fetch messages' });
    }
  });

  // POST /api/messages - Create a new message and broadcast via SSE
  app.post('/api/messages', async (req, res) => {
    try {
      const { text } = req.body;

      if (!text || !text.trim()) {
        return res.status(400).json({ error: 'Message text is required' });
      }

      const result = await db.query(
        'INSERT INTO messages (text) VALUES ($1) RETURNING id, text, created_at',
        [text.trim()]
      );

      const message = result.rows[0];
      message.created_at = message.created_at instanceof Date
        ? message.created_at.toISOString()
        : new Date(message.created_at).toISOString();

      // Broadcast to all SSE connections
      broadcastMessage(message);

      res.status(201).json(message);
    } catch (err) {
      console.error('Error creating message:', err);
      res.status(500).json({ error: 'Failed to create message' });
    }
  });

  // GET /api/stream - SSE endpoint for real-time updates
  app.get('/api/stream', (req, res) => {
    // Set SSE headers
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');
    res.setHeader('X-Accel-Buffering', 'no'); // Disable nginx buffering if behind proxy

    // Send initial comment to prevent caching issues
    res.write(': connected\n\n');

    // Add connection to active list
    const connection = res;
    sseConnections.push(connection);

    // Handle client disconnect
    req.on('close', () => {
      sseConnections = sseConnections.filter(conn => conn !== connection);
    });
  });

  function broadcastMessage(message) {
    const data = JSON.stringify(message);
    const event = `data: ${data}\n\n`;

    const disconnected = [];
    for (const conn of sseConnections) {
      try {
        if (!conn.writableEnded) {
          conn.write(event);
        } else {
          disconnected.push(conn);
        }
      } catch (err) {
        console.error('Error broadcasting to client:', err);
        disconnected.push(conn);
      }
    }

    // Clean up disconnected clients
    if (disconnected.length > 0) {
      sseConnections = sseConnections.filter(
        conn => !disconnected.includes(conn)
      );
    }
  }

  app.listen(PORT, () => {
    console.log(`Backend server running on http://localhost:${PORT}`);
  });
}

startServer().catch(err => {
  console.error('Failed to start server:', err);
  process.exit(1);
});

// DOM elements
const messageForm = document.getElementById('message-form');
const messageInput = document.getElementById('message-input');
const messageList = document.getElementById('message-list');
const sendBtn = document.getElementById('send-btn');

let eventSource = null;

/**
 * Format a date string into a readable time format.
 */
function formatTime(isoString) {
  const date = new Date(isoString);
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) +
    ' · ' + date.toLocaleDateString();
}

/**
 * Escape HTML to prevent XSS.
 */
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}

/**
 * Create a message DOM element from a message object.
 */
function createMessageElement(message) {
  const el = document.createElement('div');
  el.className = 'message';
  el.innerHTML =
    '<div class="message-text">' + escapeHtml(message.text) + '</div>' +
    '<div class="message-time">' + formatTime(message.created_at) + '</div>';
  return el;
}

/**
 * Append a message to the message list and scroll into view.
 */
function appendMessage(message) {
  const el = createMessageElement(message);
  messageList.appendChild(el);
  // Scroll to bottom smoothly
  window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
}

/**
 * Fetch initial messages from the API and render them.
 */
async function fetchMessages() {
  try {
    const response = await fetch('/api/messages');
    if (!response.ok) {
      throw new Error('Failed to fetch messages');
    }
    const messages = await response.json();
    messageList.innerHTML = '';
    messages.forEach(appendMessage);
  } catch (err) {
    console.error('Error fetching messages:', err);
  }
}

/**
 * Connect to the SSE stream for real-time updates.
 */
function connectSSE() {
  // Close existing connection if any
  if (eventSource) {
    eventSource.close();
  }

  eventSource = new EventSource('/api/stream');

  eventSource.onmessage = function (event) {
    try {
      const message = JSON.parse(event.data);
      appendMessage(message);
    } catch (err) {
      console.error('Error parsing SSE message:', err);
    }
  };

  eventSource.onerror = function () {
    console.warn('SSE connection lost. Reconnecting...');
    // EventSource will automatically attempt to reconnect
  };
}

/**
 * Handle form submission: POST a new message.
 */
async function handleSubmit(e) {
  e.preventDefault();
  const text = messageInput.value.trim();
  if (!text) return;

  // Disable input while sending
  messageInput.disabled = true;
  sendBtn.disabled = true;

  try {
    const response = await fetch('/api/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ text }),
    });

    if (!response.ok) {
      throw new Error('Failed to post message');
    }

    // Clear input (the message will appear via SSE broadcast)
    messageInput.value = '';
  } catch (err) {
    console.error('Error posting message:', err);
    // Re-enable even on error so user can retry
    messageInput.disabled = false;
    sendBtn.disabled = false;
  }

  messageInput.disabled = false;
  sendBtn.disabled = false;
  messageInput.focus();
}

// Initialize the app
messageForm.addEventListener('submit', handleSubmit);
fetchMessages();
connectSSE();

